WITH unpacked AS (SELECT id, customer_id, created_at, items, ship_to, attributes, TRY_CAST(attributes['weight_kg'] AS DOUBLE) AS weight_kg, ARRAY_CONTAINS(coupon_codes, 'VIP') AS used_vip, ARRAY_MAX(TRANSFORM(items, li -> li.price)) AS max_item_price, ship_to.zip AS ship_zip, EXISTS(items, li -> li.price > 100) AS has_premium_item FROM carts) SELECT customer_id, DATE_TRUNC('HOUR', created_at) AS hour_window, APPROX_PERCENTILE(weight_kg, ARRAY(0.25, 0.5, 0.75)) AS weight_kg_quartiles, APPROX_PERCENTILE(max_item_price, 0.5) AS max_item_price_p50, APPROX_PERCENTILE(max_item_price, 0.9) AS max_item_price_p90, PERCENTILE_APPROX(max_item_price, 0.5) AS max_item_price_p50_2, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS duration_min, AVG(max_item_price) AS avg_max_item_price FROM unpacked GROUP BY customer_id, DATE_TRUNC('HOUR', created_at) ORDER BY customer_id DESC NULLS LAST
